/**
 * Farplane UI - quest tracker (Ember Dock spec incoming/ember_wiring WIRING.md Q1-Q7): a panel that
 * slides in from the right edge with your tracked quests and each one's next step.
 *
 * Engine ported from the questtracker addon (Spongeh). The quest data (names, steps, cutscenes, key
 * items, items) is compiled in: src/data/quest_db.hpp, generated by tools/gen_quest_db.cpp from the
 * addon's data (steps from PhoenixXI's LandSandBoat quest scripts, GPL-3.0, plus its hand-written
 * overrides). Nothing is read from addons or Lua at run time.
 *   - 0x056: 32 bytes of quest flags at +0x04, port (int16) at +0x24. Ports 0x50..0x80 step 8 are the
 *     current quests of logs 0-6 (San d'Oria, Bastok, Windurst, Jeuno, Other Areas, Outlands, Aht
 *     Urhgan); 0x90..0xC0 the completed ones. Quest id = log * 1000 + bit.
 *   - 0x032 / 0x034 cutscenes (zone, cutscene) finish the step that lists them; holding a step's key
 *     item finishes it and everything before it. Steps never move back on their own.
 * State per character in <Ashita>\config\farplaneui\quests_<name>.txt; the first time, the addon's
 * own saved state (config\addons\questtracker\<name>_*\settings.lua) is imported.
 */
#include "common.hpp"
#include "../ember.hpp"
#include "../data/quest_db.hpp"

#include <fstream>
#include <sstream>

namespace farplaneui
{
    namespace
    {
        constexpr const char* kLogNames[] = {"San d'Oria", "Bastok", "Windurst", "Jeuno", "Other Areas", "Outlands", "Aht Urhgan"};
        auto Now(void) -> double { return static_cast<double>(::GetTickCount64()) / 1000.0; }
        auto Install(IAshitaCore* core) -> std::string
        {
            std::string dir = core->GetInstallPath();
            while (!dir.empty() && (dir.back() == '\\' || dir.back() == '/'))
                dir.pop_back();
            return dir + "\\";
        }
        auto U16(const uint8_t* d, uint32_t size, uint32_t off) -> uint32_t
        {
            return off + 2 <= size ? static_cast<uint32_t>(d[off] | (d[off + 1] << 8)) : 0u;
        }
        // Word-wrap to at most `lines` lines of `width` px (ellipsis on the last).
        auto Wrap(IGuiManager* gui, const std::string& text, float width, int lines) -> std::vector<std::string>
        {
            std::vector<std::string> out;
            std::istringstream ss(text);
            std::string word, cur;
            while (ss >> word)
            {
                const std::string next = cur.empty() ? word : cur + " " + word;
                if (gui->CalcTextSize(next.c_str()).x <= width || cur.empty())
                {
                    cur = next;
                    continue;
                }
                out.push_back(cur);
                cur = word;
                if (static_cast<int>(out.size()) == lines)
                    break;
            }
            if (!cur.empty() && static_cast<int>(out.size()) < lines)
                out.push_back(cur);
            else if (static_cast<int>(out.size()) == lines && !cur.empty())
            {
                std::string& last = out.back();
                while (!last.empty() && gui->CalcTextSize((last + "...").c_str()).x > width)
                    last.pop_back();
                last += "...";
            }
            return out;
        }
    } // namespace

    // ---------------------------------------------------------------- data
    void QuestModule::LoadData(Context& ctx)
    {
        (void)ctx;
        dataTried_ = true;
        quests_.clear();
        for (const auto& d : data::kQuests)
        {
            if (d.name == nullptr || d.name[0] == '\0')
                continue;
            Quest q;
            q.id = d.id, q.log = d.log;
            q.key = d.key, q.name = d.name, q.startNpc = d.npc, q.startZone = d.zone, q.startGrid = d.grid, q.note = d.note;
            for (int i = 0; i < d.stepN; ++i)
            {
                const auto& sd = data::kQuestSteps[d.step0 + i];
                Step st;
                st.text = sd.text, st.zone = sd.zone, st.grid = sd.grid, st.ki = sd.ki;
                for (int k = 0; k < sd.evN; ++k)
                    st.ev.emplace_back(data::kQuestEvs[sd.ev0 + k].zone, data::kQuestEvs[sd.ev0 + k].cs);
                for (int k = 0; k < sd.needN; ++k)
                    st.need.push_back({data::kQuestNeeds[sd.need0 + k].id, data::kQuestNeeds[sd.need0 + k].qty, data::kQuestNeeds[sd.need0 + k].name});
                for (int k = 0; k < sd.needKiN; ++k)
                    st.needKi.emplace_back(data::kQuestNeedKis[sd.needKi0 + k].id, data::kQuestNeedKis[sd.needKi0 + k].name);
                q.steps.push_back(std::move(st));
            }
            quests_[q.id] = std::move(q);
        }
        dataStatus_ = std::to_string(quests_.size()) + " quests built in";
    }

    // ---------------------------------------------------------------- state (per character)
    auto QuestModule::StatePath(Context& ctx) const -> std::string
    {
        const std::string dir = Install(ctx.core) + "config\\farplaneui";
        ::CreateDirectoryA(dir.c_str(), nullptr);
        return dir + "\\quests_" + char_ + ".txt";
    }
    void QuestModule::LoadState(Context& ctx)
    {
        active_.clear(), completed_.clear(), tracked_.clear(), step_.clear();
        std::ifstream f(StatePath(ctx));
        if (!f)
        {
            ImportAddon(ctx);
            return;
        }
        std::string line;
        auto ids = [](const std::string& v, std::set<int>& out) {
            std::istringstream ss(v);
            std::string t;
            while (std::getline(ss, t, ','))
                if (!t.empty())
                    out.insert(std::atoi(t.c_str()));
        };
        while (std::getline(f, line))
        {
            const size_t eq = line.find('=');
            if (eq == std::string::npos)
                continue;
            const std::string k = line.substr(0, eq), v = line.substr(eq + 1);
            if (k == "active")
                ids(v, active_);
            else if (k == "completed")
                ids(v, completed_);
            else if (k == "tracked")
                ids(v, tracked_);
            else if (k == "step")
            {
                std::istringstream ss(v);
                std::string t;
                while (std::getline(ss, t, ','))
                    if (const size_t c = t.find(':'); c != std::string::npos)
                        step_[std::atoi(t.substr(0, c).c_str())] = std::atoi(t.substr(c + 1).c_str());
            }
        }
    }
    void QuestModule::SaveState(Context& ctx)
    {
        if (char_.empty())
            return;
        std::ofstream f(StatePath(ctx), std::ios::trunc);
        auto list = [&](const char* k, const std::set<int>& s) {
            f << k << "=";
            bool first = true;
            for (const int id : s)
                f << (first ? "" : ",") << id, first = false;
            f << "\n";
        };
        list("active", active_);
        list("completed", completed_);
        list("tracked", tracked_);
        f << "step=";
        bool first = true;
        for (const auto& [id, n] : step_)
            f << (first ? "" : ",") << id << ":" << n, first = false;
        f << "\n";
        stateDirty_ = false;
    }
    // First run for a character: take the questtracker addon's saved state if there is one.
    void QuestModule::ImportAddon(Context& ctx)
    {
        const std::string base = Install(ctx.core) + "config\\addons\\questtracker\\";
        WIN32_FIND_DATAA fd{};
        HANDLE h = ::FindFirstFileA((base + char_ + "_*").c_str(), &fd);
        if (h == INVALID_HANDLE_VALUE)
            return;
        const std::string dir = base + fd.cFileName + "\\settings.lua";
        ::FindClose(h);
        std::ifstream f(dir);
        std::string line;
        int n = 0;
        while (std::getline(f, line))
        {
            // settings["active"]["1234"] = true;   settings["step"]["1234"] = 3;
            char table[16]{}, id[16]{}, val[16]{};
            if (::sscanf_s(line.c_str(), "settings[\"%15[^\"]\"][\"%15[^\"]\"] = %15[^;]", table, 16, id, 16, val, 16) != 3)
                continue;
            const std::string t = table;
            const int q = std::atoi(id);
            if (t == "active" && std::string(val) == "true")
                active_.insert(q), ++n;
            else if (t == "completed" && std::string(val) == "true")
                completed_.insert(q);
            else if (t == "tracked" && std::string(val) == "true")
                tracked_.insert(q);
            else if (t == "step")
                step_[q] = std::atoi(val);
        }
        if (n > 0)
            ctx.Print("Quests: imported " + std::to_string(n) + " active quests from the questtracker addon.");
        stateDirty_ = true;
    }

    // ---------------------------------------------------------------- engine
    auto QuestModule::StepOf(int id) const -> int
    {
        const auto it = step_.find(id);
        return it != step_.end() ? it->second : 1;
    }
    void QuestModule::SetStep(Context& ctx, int id, int n, bool announce)
    {
        const auto q = quests_.find(id);
        if (q == quests_.end() || q->second.steps.empty())
            return;
        n = std::clamp(n, 1, static_cast<int>(q->second.steps.size()) + 1);
        const int old = StepOf(id);
        step_[id]     = n;
        stateDirty_   = true;
        if (announce && n > old)
            ctx.Print(n > static_cast<int>(q->second.steps.size()) ? "Quests: " + q->second.name + ": all steps done - finish it to complete the quest."
                                                                     : "Quests: " + q->second.name + ": next, " + q->second.steps[static_cast<size_t>(n - 1)].text);
    }
    void QuestModule::IncomingPacket(Context& ctx, uint16_t id, uint32_t size, const uint8_t* data)
    {
        if (data == nullptr)
            return;
        if (id == 0x056 && size >= 0x26)
        {
            const uint32_t port = U16(data, size, 0x24);
            const bool current  = port >= 0x50 && port <= 0x80 && port % 8 == 0;
            const bool done     = port >= 0x90 && port <= 0xC0 && port % 8 == 0;
            if (!current && !done)
                return;
            const int log = static_cast<int>((port - (current ? 0x50 : 0x90)) / 8);
            std::set<int> set;
            for (int byte = 0; byte < 32; ++byte)
                for (int b = 0; b < 8; ++b)
                    if ((data[0x04 + byte] >> b) & 1)
                        set.insert(log * 1000 + byte * 8 + b);
            if (current)
            {
                for (auto it = active_.begin(); it != active_.end();)
                    it = (*it / 1000 == log && set.count(*it) == 0) ? active_.erase(it) : std::next(it);
                for (const int q : set)
                    if (quests_.count(q) != 0 && active_.insert(q).second && seenLog_.count(log) != 0)
                    {
                        tracked_.insert(q); // new quest: track it
                        ctx.Print("Quests: new quest - " + quests_[q].name + " (tracking).");
                    }
                seenLog_.insert(log);
            }
            else
                for (const int q : set)
                    if (completed_.insert(q).second)
                    {
                        const bool mine = active_.erase(q) + tracked_.erase(q) > 0;
                        step_.erase(q);
                        if (mine && quests_.count(q) != 0)
                            ctx.Print("Quests: complete - " + quests_[q].name + "!");
                    }
            stateDirty_ = true;
        }
        else if (id == 0x032 || id == 0x034)
        {
            const uint32_t zone = id == 0x032 ? U16(data, size, 0x0A) : U16(data, size, 0x2A);
            const uint32_t cs   = id == 0x032 ? U16(data, size, 0x0C) : U16(data, size, 0x2C);
            for (const int q : active_)
            {
                const auto it = quests_.find(q);
                if (it == quests_.end())
                    continue;
                const auto& steps = it->second.steps;
                for (int i = StepOf(q); i <= static_cast<int>(steps.size()); ++i)
                {
                    bool hit = false;
                    for (const auto& [z, c] : steps[static_cast<size_t>(i - 1)].ev)
                        hit |= static_cast<uint32_t>(z) == zone && static_cast<uint32_t>(c) == cs;
                    if (hit)
                    {
                        SetStep(ctx, q, i + 1, true);
                        break;
                    }
                }
            }
        }
    }
    void QuestModule::Frame(Context& ctx)
    {
        if (!dataTried_)
            LoadData(ctx);
        auto* party = ctx.core->GetMemoryManager()->GetParty();
        const char* me = party != nullptr ? party->GetMemberName(0) : nullptr;
        if (me != nullptr && me[0] != '\0' && char_ != me)
        {
            if (!char_.empty() && stateDirty_)
                SaveState(ctx);
            char_ = me;
            seenLog_.clear();
            LoadState(ctx);
        }
        const double now = Now();
        // Key items every 2 s: holding a later step's key item means everything before it is done.
        if (now - kiCheckAt_ > 2.0 && !char_.empty())
        {
            kiCheckAt_ = now;
            auto* player = ctx.core->GetMemoryManager()->GetPlayer();
            for (const int q : active_)
            {
                const auto it = quests_.find(q);
                if (it == quests_.end() || player == nullptr)
                    continue;
                const auto& steps = it->second.steps;
                for (int i = static_cast<int>(steps.size()); i >= StepOf(q); --i)
                    if (const int ki = steps[static_cast<size_t>(i - 1)].ki; ki > 0 && player->HasKeyItem(static_cast<uint32_t>(ki)))
                    {
                        SetStep(ctx, q, i + 1, true);
                        break;
                    }
            }
        }
        if (stateDirty_ && now - savedAt_ > 1.0)
        {
            savedAt_ = now;
            SaveState(ctx);
        }
    }
    void QuestModule::Release(void)
    {
        if (ctxSave_ != nullptr && stateDirty_)
            SaveState(*ctxSave_);
    }

    // ---------------------------------------------------------------- panel
    void QuestModule::Render(Context& ctx, IGuiManager* gui)
    {
        ctxSave_ = &ctx;
        if (!show_)
            return;
        const auto& t = ember::T();
        const float s = ctx.layout.screenH / 1080.0f;
        const double now = Now();
        const float dt = static_cast<float>(std::clamp(now - lastAt_, 0.0, 0.1));
        lastAt_ = now;
        // Slide: t_ eases toward open / closed (easeInOutCubic on the shown value).
        const float target = open_ ? 1.0f : 0.0f;
        slide_ += (target - slide_) * (1.0f - std::exp(-dt * 14.0f));
        if (std::abs(target - slide_) < 0.001f)
            slide_ = target;
        const float e  = slide_ < 0.5f ? 4 * slide_ * slide_ * slide_ : 1 - std::pow(-2 * slide_ + 2, 3.0f) / 2;
        const float W  = width_ * s, M = 12.0f * s, top = 150.0f * s;
        const float px = ctx.layout.screenW - M - W + (1.0f - e) * (W + M);
        const float maxBottom = (ctx.layout.dock.w > 0 ? ctx.layout.dock.y : ctx.layout.screenH) - 24.0f * s;

        // Rows to show: tracked quests (pinned first is the order of the set: tracked, then by log / name).
        std::vector<int> list;
        for (const int q : active_)
            if (tracked_.count(q) != 0 && quests_.count(q) != 0)
                list.push_back(q);
        std::sort(list.begin(), list.end(), [&](int a, int b) {
            const auto &qa = quests_.at(a), &qb = quests_.at(b);
            return qa.log != qb.log ? qa.log < qb.log : qa.name < qb.name;
        });

        const float tabW = 18.0f * s, tabH = 64.0f * s;
        const float h    = std::max(tabH + 8.0f * s, std::min(contentH_, maxBottom - top));
        const float tabX = e > 0.0f ? px - tabW - 4.0f * s : ctx.layout.screenW - tabW - 2.0f;
        const float tabY = top + std::min(h, maxBottom - top) * 0.5f - tabH * 0.5f;
        const ImVec2 mouse = gui->GetIO().MousePos;
        const bool overTab   = mouse.x >= tabX && mouse.x < tabX + tabW && mouse.y >= tabY && mouse.y < tabY + tabH;
        const bool overPanel = e > 0.0f && mouse.x >= px && mouse.x < px + W && mouse.y >= top && mouse.y < top + h;
        const float winX = std::min(tabX, px);
        gui->SetNextWindowPos(ImVec2(winX, top), ImGuiCond_Always);
        gui->SetNextWindowSize(ImVec2(ctx.layout.screenW - winX, h), ImGuiCond_Always);
        ImGuiWindowFlags f = ImGuiWindowFlags_NoDecoration | ImGuiWindowFlags_NoBackground | ImGuiWindowFlags_NoSavedSettings |
                             ImGuiWindowFlags_NoFocusOnAppearing | ImGuiWindowFlags_NoNav | ImGuiWindowFlags_NoBringToFrontOnFocus |
                             ImGuiWindowFlags_NoScrollWithMouse | ImGuiWindowFlags_NoScrollbar;
        if (!overTab && !overPanel)
            f |= ImGuiWindowFlags_NoInputs; // clicks pass through to the game everywhere else
        gui->PushStyleVar(ImGuiStyleVar_WindowPadding, ImVec2(0, 0));
        if (gui->Begin("##fpui_quests", nullptr, f))
        {
            // Tab: rounded, amber edge, ember accent on its left, chevron.
            ember::RoundRect(gui, ImVec2(tabX, tabY), ImVec2(tabW, tabH), t.glass, t.amber, tabW * 0.5f, 1.0f);
            if (ctx.white != nullptr)
                ui::ImageAt(gui, ctx.white, ImVec2(tabX + 2, tabY + tabH * 0.25f), ImVec2(2, tabH * 0.5f), ImVec2(0, 0), ImVec2(1, 1), t.ember, 0.8f);
            ember::TextCenter(gui, tabX + tabW * 0.5f + 1, tabY + (tabH - gui->GetTextLineHeight()) * 0.5f, t.amber, open_ ? ">" : "<");
            gui->SetCursorScreenPos(ImVec2(tabX, tabY));
            if (gui->InvisibleButton("##qtab", ImVec2(tabW, tabH)))
            {
                open_ = !open_;
                ctx.MarkDirty();
            }
            if (gui->IsItemHovered())
                gui->SetTooltip(open_ ? "Hide quests (/fpui quests)" : "Show quests (/fpui quests)");

            if (e > 0.0f)
            {
                if (overPanel && gui->GetIO().MouseWheel != 0.0f)
                    scroll_ = std::max(0.0f, scroll_ - gui->GetIO().MouseWheel * 40.0f * s);
                scroll_ = std::min(scroll_, std::max(0.0f, contentH_ - h));
                ember::RoundRect(gui, ImVec2(px, top), ImVec2(W, h), t.glass, t.edge, 10.0f * s, 1.0f);
                const float pad = 16.0f * s, iw = W - 2 * pad;
                float y = top + pad - scroll_;
                // Header: Quests + count pill + hint, divider.
                gui->PushFont(nullptr, std::max(11.0f, 14.0f * s));
                ember::Text(gui, ImVec2(px + pad, y), t.amber, "Quests");
                const float hw = gui->CalcTextSize("Quests").x;
                const float lh = gui->GetTextLineHeight();
                gui->PopFont();
                gui->PushFont(nullptr, std::max(9.0f, 10.0f * s));
                char cnt[8]{};
                ::sprintf_s(cnt, "%zu", list.size());
                const ImVec2 cs(gui->CalcTextSize(cnt).x + 12.0f * s, std::max(14.0f * s, gui->GetTextLineHeight() + 2));
                ember::RoundRect(gui, ImVec2(px + pad + hw + 8 * s, y + (lh - cs.y) * 0.5f), cs, t.track, t.edgeDim, cs.y * 0.5f, 1.0f);
                ember::TextCenter(gui, px + pad + hw + 8 * s + cs.x * 0.5f, y + (lh - gui->GetTextLineHeight()) * 0.5f, t.amber, cnt);
                ember::TextRight(gui, px + W - pad, y + (lh - gui->GetTextLineHeight()) * 0.5f, t.muted, "/fpui quests");
                gui->PopFont();
                y += lh + 8 * s;
                if (ctx.white != nullptr)
                    ui::ImageAt(gui, ctx.white, ImVec2(px + pad, y), ImVec2(iw, 1), ImVec2(0, 0), ImVec2(1, 1), Rgba{t.amber.r, t.amber.g, t.amber.b, 40.0f / 255.0f});
                y += 8 * s;

                if (list.empty())
                {
                    gui->PushFont(nullptr, std::max(9.0f, 11.0f * s));
                    const char* msg = quests_.empty() ? "No quest data."
                                      : active_.empty() ? "No quests yet. Zone once so the server sends your quest log."
                                                        : "Nothing tracked. Pick quests in /fpui > Quests.";
                    for (const auto& l : Wrap(gui, msg, iw, 3))
                    {
                        ember::Text(gui, ImVec2(px + pad, y), t.dim, l.c_str());
                        y += gui->GetTextLineHeight();
                    }
                    gui->PopFont();
                }
                const int maxShown = expanded_ ? 999 : 3;
                int shown = 0;
                for (const int q : list)
                {
                    if (shown++ >= maxShown)
                        break;
                    const Quest& qd = quests_.at(q);
                    const int n = StepOf(q), total = static_cast<int>(qd.steps.size());
                    const Step* st = n >= 1 && n <= total ? &qd.steps[static_cast<size_t>(n - 1)] : nullptr;
                    const float y0 = y;
                    // measure the card
                    gui->PushFont(nullptr, std::max(10.0f, 12.0f * s));
                    const float titleH = gui->GetTextLineHeight();
                    gui->PopFont();
                    gui->PushFont(nullptr, std::max(9.0f, 10.0f * s));
                    const float smallH = gui->GetTextLineHeight();
                    const std::string stepText = st != nullptr ? st->text : total > 0 ? "All steps done - finish it to complete the quest."
                                                                                       : (qd.startNpc.empty() ? std::string("No step list for this quest yet.")
                                                                                                              : "Started by " + qd.startNpc + " in " + qd.startZone + " (" + qd.startGrid + ").");
                    const auto lines = Wrap(gui, stepText, iw - 22 * s, 2);
                    gui->PopFont();
                    const float cardH = titleH + smallH + smallH * static_cast<float>(lines.size()) + (total > 1 ? 12 * s : 0) + 14 * s;
                    ember::RoundRect(gui, ImVec2(px + pad - 6 * s, y0 - 4 * s), ImVec2(iw + 12 * s, cardH), ember::Hex(0xcf733e22), ember::Hex(0xe6b47950), 8 * s, 1.0f);
                    // star (click: untrack)
                    gui->PushFont(nullptr, std::max(10.0f, 12.0f * s));
                    ember::Text(gui, ImVec2(px + pad, y), ember::Hex(0xf2c45aff), "*");
                    gui->SetCursorScreenPos(ImVec2(px + pad - 2, y));
                    gui->PushID(q);
                    if (gui->InvisibleButton("##star", ImVec2(14 * s, titleH)))
                    {
                        tracked_.erase(q);
                        stateDirty_ = true;
                    }
                    if (gui->IsItemHovered())
                        gui->SetTooltip("Untrack");
                    ember::Text(gui, ImVec2(px + pad + 16 * s, y), t.ivory, qd.name.c_str());
                    // title: right-click = step done, ctrl+right-click = undo
                    gui->SetCursorScreenPos(ImVec2(px + pad + 16 * s, y));
                    gui->InvisibleButton("##title", ImVec2(iw - 16 * s, titleH));
                    if (gui->IsItemHovered())
                    {
                        gui->SetTooltip("Right-click: step done   Shift+right-click: undo a step");
                        if (gui->IsMouseClicked(ImGuiMouseButton_Right))
                            SetStep(ctx, q, n + (gui->GetIO().KeyShift ? -1 : 1), true);
                    }
                    gui->PopID();
                    gui->PopFont();
                    y += titleH;
                    gui->PushFont(nullptr, std::max(9.0f, 10.0f * s));
                    const std::string where = std::string(qd.log >= 0 && qd.log < 7 ? kLogNames[qd.log] : "Quest") +
                                              (st != nullptr && !st->zone.empty() ? "  -  " + st->zone + (st->grid.empty() ? "" : " (" + st->grid + ")") : "");
                    ember::Text(gui, ImVec2(px + pad + 16 * s, y), t.muted, where.c_str());
                    y += smallH;
                    for (const auto& l : lines)
                    {
                        ember::Text(gui, ImVec2(px + pad + 16 * s, y), t.dim, l.c_str());
                        y += smallH;
                    }
                    if (total > 1)
                    {
                        y += 3 * s;
                        const float bw = iw - 16 * s - 40 * s;
                        ember::Bar(ctx, gui, ImVec2(px + pad + 16 * s, y + 1), ImVec2(bw, 6 * s), static_cast<float>(std::min(n - 1, total)) / total, t.ember);
                        char pr[16]{};
                        ::sprintf_s(pr, "%d/%d", std::min(n - 1, total), total);
                        ember::TextRight(gui, px + pad + iw, y + 4 * s - gui->GetTextLineHeight() * 0.5f, t.amber, pr);
                        y += 9 * s;
                    }
                    gui->PopFont();
                    y = y0 + cardH + 6 * s;
                }
                if (static_cast<int>(list.size()) > 3)
                {
                    gui->PushFont(nullptr, std::max(9.0f, 10.0f * s));
                    char more[32]{};
                    ::sprintf_s(more, expanded_ ? "- show less" : "+ %d more", static_cast<int>(list.size()) - 3);
                    ember::Text(gui, ImVec2(px + pad, y), t.amber, more);
                    gui->SetCursorScreenPos(ImVec2(px + pad, y));
                    if (gui->InvisibleButton("##more", ImVec2(iw, gui->GetTextLineHeight())))
                        expanded_ = !expanded_;
                    y += gui->GetTextLineHeight() + 4 * s;
                    gui->PopFont();
                }
                contentH_ = y + scroll_ - top + pad - 8 * s;
            }
            gui->SetCursorScreenPos(ImVec2(winX, top));
            gui->Dummy(ImVec2(0, 0));
        }
        gui->End();
        gui->PopStyleVar();
    }

    // ---------------------------------------------------------------- settings: pick what to track
    void QuestModule::RenderSettings(Context& ctx, IGuiManager* gui)
    {
        cfg::Grid g(gui, ctx);
        bool ch = g.Toggle("Enabled", "Quest panel on the right edge (Alt+Q with /bind !q /fpui quests).", show_);
        ch |= g.Toggle("Open", "Panel slid in (the tab on the edge toggles it too).", open_);
        ch |= g.Slider("Width", "Panel width at 1080p.", width_, 220.0f, 480.0f, "%.0f");
        if (ch)
            ctx.MarkDirty();
        g.Info("Data", dataStatus_.empty() ? "not loaded yet" : dataStatus_.c_str());
        g.Info("Character", char_.empty() ? "not logged in" : char_.c_str());
        g.Section("Your quests - tick to track");
        if (active_.empty())
            g.Info("Quest log", "Empty so far. Zone once so the server sends your quest log.");
        std::vector<int> list(active_.begin(), active_.end());
        std::sort(list.begin(), list.end(), [&](int a, int b) {
            const auto ia = quests_.find(a), ib = quests_.find(b);
            const int la = a / 1000, lb = b / 1000;
            if (la != lb)
                return la < lb;
            return (ia != quests_.end() ? ia->second.name : "") < (ib != quests_.end() ? ib->second.name : "");
        });
        int lastLog = -1;
        for (const int q : list)
        {
            const auto it = quests_.find(q);
            const std::string name = it != quests_.end() ? it->second.name : "Quest " + std::to_string(q);
            if (q / 1000 != lastLog)
            {
                lastLog = q / 1000;
                gui->TextColored(ToVec4(art::amber), "%s", lastLog >= 0 && lastLog < 7 ? kLogNames[lastLog] : "Other");
            }
            gui->PushID(q);
            bool on = tracked_.count(q) != 0;
            if (gui->Checkbox("##track", &on))
            {
                if (on)
                    tracked_.insert(q);
                else
                    tracked_.erase(q);
                stateDirty_ = true;
            }
            gui->SameLine();
            gui->TextUnformatted(name.c_str());
            const int total = it != quests_.end() ? static_cast<int>(it->second.steps.size()) : 0;
            if (total > 0)
            {
                // Step: < n/total > (set how far along you are)
                const int n = StepOf(q);
                gui->SameLine(std::max(gui->GetCursorPosX() + 8.0f, gui->GetContentRegionAvail().x * 0.0f + 360.0f));
                if (gui->SmallButton("<"))
                    SetStep(ctx, q, n - 1, false);
                gui->SameLine();
                gui->Text("step %d/%d", std::min(n, total + 1) > total ? total : n, total);
                gui->SameLine();
                if (gui->SmallButton(">"))
                    SetStep(ctx, q, n + 1, false);
                if (n <= total && gui->IsItemHovered())
                    gui->SetTooltip("%s", it->second.steps[static_cast<size_t>(n - 1)].text.c_str());
            }
            gui->PopID();
        }
        gui->Dummy(ImVec2(0, 4));
        if (!list.empty())
        {
            if (gui->Button("Track all"))
            {
                tracked_.insert(list.begin(), list.end());
                stateDirty_ = true;
            }
            gui->SameLine();
            if (gui->Button("Track none"))
            {
                tracked_.clear();
                stateDirty_ = true;
            }
        }
    }

    void QuestModule::Load(IConfigurationManager* cfg, const char* alias)
    {
        show_  = cfg->GetBool(alias, "quests", "show", show_);
        open_  = cfg->GetBool(alias, "quests", "open", open_);
        width_ = std::clamp(cfg->GetFloat(alias, "quests", "width", width_), 220.0f, 480.0f);
        slide_ = open_ ? 1.0f : 0.0f;
    }
    void QuestModule::Save(IConfigurationManager* cfg, const char* alias) const
    {
        ui::SetB(cfg, alias, "quests", "show", show_);
        ui::SetB(cfg, alias, "quests", "open", open_);
        ui::SetF(cfg, alias, "quests", "width", width_);
    }
    auto QuestModule::Command(Context& ctx, const std::vector<std::string>& args) -> bool
    {
        const std::string sub = args.empty() ? std::string() : ui::Lower(args[0]);
        if (sub.empty() || sub == "toggle")
            open_ = !open_;
        else if (sub == "open" || sub == "close")
            open_ = sub == "open";
        else if (sub == "show" || sub == "hide")
            show_ = sub == "show";
        else if (sub == "next" || sub == "back")
        {
            // the first tracked quest (panel order)
            int best = -1;
            for (const int q : active_)
                if (tracked_.count(q) != 0 && quests_.count(q) != 0 && (best < 0 || q / 1000 < best / 1000 ||
                                                                          (q / 1000 == best / 1000 && quests_[q].name < quests_[best].name)))
                    best = q;
            if (best >= 0)
                SetStep(ctx, best, StepOf(best) + (sub == "next" ? 1 : -1), true);
            return true;
        }
        else if (sub == "debug")
        {
            ctx.Print("Quests: " + dataStatus_ + "; " + std::to_string(active_.size()) + " active, " + std::to_string(tracked_.size()) + " tracked, " +
                      std::to_string(completed_.size()) + " completed; state " + (char_.empty() ? std::string("-") : StatePath(ctx)));
            return true;
        }
        else
        {
            ctx.Print("/fpui quests [open|close|show|hide] | next | back | debug   (tick quests to track in /fpui > Quests)");
            return true;
        }
        ctx.MarkDirty();
        return true;
    }
} // namespace farplaneui
